<?php
/** Official scoreboard and starting/bench lists; no invented coordinates or player minutes. */
use app\services\TeamUi;
$this->title=($model->homeTeam?->name??'待定').' 对 '.($model->awayTeam?->name??'待定');
?>
<a class="back-link" href="/worldcup">← 赛程与比分</a>
<section class="match-detail match-scoreboard"><div class="match-round"><?= e($model->stage) ?><?= $model->group_name?' · '.e($model->group_name).' 组':'' ?><span>第 <?= (int)$model->match_number ?> 场</span></div><h1 class="match-opponents"><span><?= TeamUi::flag($model->homeTeam) ?><a href="/teams/<?= e($model->homeTeam?->slug) ?>"><?= e($model->homeTeam?->name) ?></a></span><span class="big-score"><?= e($model->home_score??'—') ?><i>:</i><?= e($model->away_score??'—') ?></span><span><?= TeamUi::flag($model->awayTeam) ?><a href="/teams/<?= e($model->awayTeam?->slug) ?>"><?= e($model->awayTeam?->name) ?></a></span></h1><?php if($model->home_penalty_score!==null): ?><p>点球 <?= (int)$model->home_penalty_score ?> : <?= (int)$model->away_penalty_score ?></p><?php endif ?><div class="match-status"><?= $model->status==='finished'?'比赛结束':'赛程' ?></div><p><?= e($model->starts_at) ?> 协调世界时</p><span><?= e($model->venue?->name_cn?:$model->venue?->name_original) ?></span></section>
<?= $this->render('_source',['model'=>$model]) ?>
<?php if($model->stats): ?><section class="section"><h2>比赛统计</h2><div class="table-scroll"><table><thead><tr><th>球队</th><th>控球</th><th>射门</th><th>射正</th><th>角球</th></tr></thead><tbody><?php foreach($model->stats as $s): ?><tr><th><?= TeamUi::label($s->team) ?></th><?php foreach(['possession','shots','shots_on_target','corners'] as $field): ?><td><?= e($s->$field??'—') ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div></section><?php endif ?>
<?php if($model->events): ?><section class="section"><h2>比赛事件</h2><ol class="event-list"><?php foreach($model->events as $event): ?><li><b><?= e($event->minute??'—') ?>′</b><span><?= e($event->event_type) ?></span><span><?= e($event->player?->name??'') ?></span></li><?php endforeach ?></ol></section><?php endif ?>
<section class="section"><div class="section-head"><h2>比赛阵容</h2><a href="/forum/new?match_id=<?= (int)$model->id ?>">讨论这场比赛 ↗</a></div><div class="lineup-sides"><?php foreach([$model->homeTeam,$model->awayTeam] as $team): ?><article class="lineup-panel"><h3><?= TeamUi::label($team) ?></h3><?php foreach([1=>'首发阵容',0=>'替补名单'] as $start=>$label): ?><h4><?= e($label) ?></h4><ol><?php foreach($model->lineups as $line): ?><?php if((int)$line->team_id!==(int)$team?->id||(int)$line->is_starting_xi!==$start)continue;$raw=is_array($line->raw_payload_json)?$line->raw_payload_json:json_decode($line->raw_payload_json??'{}',true); ?><li><span class="lineup-shirt"><?= e($raw['ShirtNumber']??$line->player?->shirt_number??'—') ?></span><?php if($line->player): ?><a href="/players/<?= e($line->player->slug) ?>"><?= e($line->officialPlayerName) ?></a><?php else: ?><span><?= e($line->officialPlayerName) ?></span><?php endif ?><span class="lineup-position"><?= e(['GK'=>'门将','DF'=>'后卫','MF'=>'中场','FW'=>'前锋'][$line->tactical_position]??'') ?></span></li><?php endforeach ?></ol><?php endforeach ?></article><?php endforeach ?></div></section>
